/* All data changes are explicit user records. No external account actions. */
(async()=>{
'use strict';
const D=await fetch('data.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()});
const M=CommandModel,E=M.escape,$=s=>document.querySelector(s),KEY='contest-command-evidence-v1';
let state={schema:1,plan:'contest-command-2026',records:{},capacity:{weekday:null,saturday:null,sunday:null}},storageWarning='';
try{const raw=localStorage.getItem(KEY);if(raw)state=M.validate(JSON.parse(raw),D.tasks);}catch{storageWarning='Saved records could not be read. Nothing was counted complete; import a valid backup.';}
let filter='all',range='build',statusFilter='all',editing=null,pendingImport=null;
const project=p=>D.projects.find(x=>x.id===p),eff=t=>M.effective(t.id,state.records,D.tasks),hours=m=>Number((m/60).toFixed(2)),sum=ts=>ts.reduce((s,t)=>s+t.minutes,0),done=ts=>ts.filter(t=>eff(t)==='done').length;
const dateLabel=d=>new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric',timeZone:'America/Chicago'}).format(new Date(d+'T12:00:00Z'));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const tag=p=>`<span class="tag" style="border-left:3px solid ${project(p).color}">${E(p.toUpperCase())}</span>`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageWarning='';}catch{storageWarning='Browser storage failed. Export a backup now; changes may be lost on reload.';}}
function section(title,html){return `<section><h2>${title}</h2>${html}</section>`;}
function metric(value,label,sub){return `<div class="metric"><strong>${value}</strong>${label}<small>${sub}</small></div>`;}
function clock(){ $('#clock').textContent=new Intl.DateTimeFormat('en-US',{dateStyle:'full',timeStyle:'short',timeZone:'America/Chicago'}).format(new Date())+' · America/Chicago';
 $('#countdowns').innerHTML=D.projects.map(p=>{let m=Math.max(0,Math.floor((Date.parse(p.deadline)-Date.now())/60000));let time=m?`${Math.floor(m/1440)}d ${Math.floor(m%1440/60)}h ${m%60}m`:'Deadline passed';return `<a class="cd" style="--c:${p.color}" href="#${p.id}"><b>${E(p.name)}</b><small>${E(p.when)} · HARD CLOSE</small><strong>${time}</strong><small>Target: ${E(p.target)}</small></a>`;}).join('');}
function portfolio(){const build=D.tasks.filter(t=>t.date<='2026-11-18');return section('The portfolio at a glance',`<p>Four active lanes, one person’s time. This is a <b>full-scope recovery proposal</b>, not a promise that all work fits. Hours are planning estimates; capacity has not been confirmed.</p><div class="grid">${metric('4','Contests tracked','Separate entries and repositories')}${metric(hours(sum(build))+'h','Estimated work through Nov 18','Includes 1h emergency verification')}${metric(done(build)+' / '+build.length,'Recovery tasks recorded done','Unique tasks, not contest readiness')}${metric('Chess handoff','Living Table current focus','29-check acceptance rundown · updated Oct 29')}</div><div class="callout"><b>Historical schedule retained.</b>The original October 25 estimates below have not been re-estimated against current chess scope. Use the linked chess rundown for current Living Table work. No test or submission is inferred from its date.</div><div class="actions"><a class="button" href="#schedule">Open daily execution →</a><a class="button" href="#comparison">Review what changed</a></div>`)+section('Projects & next evidence',D.projects.map(p=>{const ts=D.tasks.filter(t=>t.project===p.id&&t.date<='2026-11-18');return `<article class="project" style="--c:${p.color}"><div><h3><a href="#${p.id}">${E(p.name)} ↗</a></h3><span class="status">${E(p.status)}</span><p class="sub">Baseline: ${p.id==='lt'?'Oct 29':'Oct 25'}</p></div><div>${E(p.baseline)}<p><b>Next:</b> ${E(p.next)}</p></div><div><b>${hours(sum(ts))}h proposed</b><p class="sub">${done(ts)} / ${ts.length} recovery tasks recorded done</p><div class="bar"><i style="width:${done(ts)/ts.length*100}%"></i></div><p class="sub">Hard close: ${E(p.when)}</p></div></article>`}).join(''))+section('Dependencies that control the schedule',`<div class="two"><div><div class="risk"><b>Today → Oct 26 · account and foundation checks</b>Verify Meta acceptance, Start status, relevant rules and disclosure questions. Run the Quest baseline and back up untracked source.</div><div class="risk"><b>Oct 29–30 · first complete Living Table game</b>Rules and round state must exist before AI, pacing, audio and five-tester validation. Miss this gate: re-estimate the remaining work immediately.</div><div class="risk"><b>Nov 9 · freeze Living Table scope</b>Candidate and tester access must be ready before the five-person playtest window. Cut cosmetic work first; failed interaction tests stay blocking.</div></div><div><div class="risk"><b>Nov 11 · Unity feature-complete</b>Packaging overlaps MegaJam’s opening. If it slips, remove Unity features and protect submission time; do not silently consume Living Table testing.</div><div class="risk"><b>Nov 12–15 · highest collision risk</b>MegaJam build, Unity submission and Living Table retests compete for the same hours. Capacity tools below expose the daily shortage.</div><div class="risk"><b>Fallback when a day does not fit</b>Remove optional effects, extra modes, optional prize lanes and full livestream attendance first. Keep legal rounds, device acceptance and submission access. If core work still exceeds time, scope or staffing must change.</div></div></div>`);}
function capacityPanel(){const dates=[...new Set(D.tasks.filter(t=>t.date<='2026-11-18').map(t=>t.date))];const loads=dates.map(d=>({d,h:hours(sum(D.tasks.filter(t=>t.date===d))),c:M.capacityFor(d,state.capacity)}));const short=loads.filter(x=>x.c!=null&&x.h>x.c);return `<p>Enter <b>hours actually available after family and other commitments</b>. These fields are blank because availability is unknown. Work is sequential, not simultaneous; estimates include implementation and review but no contingency margin.</p><div class="capacity">${[['weekday','Weekday hours'],['saturday','Saturday hours'],['sunday','Sunday hours']].map(([k,l])=>`<label>${l}<input type="number" data-capacity="${k}" min="0" max="24" step="0.5" value="${state.capacity[k]??''}" placeholder="Unset"></label>`).join('')}<button id="save-capacity">Update capacity</button></div><p class="${short.length?'bad':'sub'}">${short.length?`${short.length} days exceed capacity by ${Number(short.reduce((s,x)=>s+x.h-x.c,0).toFixed(2))}h in total. Spare hours on later days do not resolve earlier dependencies automatically.`:loads.some(x=>x.c==null)?'Capacity is unconfirmed. No feasible-schedule claim is being made.':'Every estimated day fits the entered hours; this does not prove task completion or allow contingency.'}</p><div class="timeline" aria-label="Daily estimated hours through November 18">${loads.map(x=>`<div><span title="${x.d}">${x.d.slice(8)}</span><div class="load ${x.c!=null&&x.h>x.c?'over':''}" title="${x.d}: ${x.h} hours"><i style="height:${x.h/12*100}%"></i></div><span>${x.h}h</span></div>`).join('')}</div><p class="sub">Oct 25 → Nov 18 · red = over your capacity · peak ${Math.max(...loads.map(x=>x.h))}h. Completing tasks changes execution totals, not the original estimated load.</p>`;}
function taskRow(t){let s=eff(t),r=state.records[t.id];let missing=t.depends.filter(id=>M.effective(id,state.records,D.tasks)!=='done');return `<article class="task ${s}"><div>${tag(t.project)}<p>${hours(t.minutes)}h estimate</p><span class="status ${s==='done'?'good':s==='blocked'?'bad':''}">${E(s)}</span></div><div><h4>${E(t.title)}</h4><p>${E(t.output)}</p><p class="sub">${E(t.owner)}${missing.length?' · '+missing.length+' prerequisite record(s) still open':''}</p>${r?.note?`<p class="note">Record: ${E(r.note)}</p><small>${E(r.updated)}${r.status==='done'&&s!=='done'?' · Reopened by an incomplete prerequisite':''}</small>`:''}</div><button data-task="${E(t.id)}">${r?'Edit record':'Record result'}</button></article>`;}
function schedule(p=null){const ts=D.tasks.filter(t=>(p?t.project===p:filter==='all'||t.project===filter)&&(range==='all'||(range==='build'?t.date<='2026-11-18':t.date>='2026-11-19'))&&(statusFilter==='all'||(statusFilter==='open'?eff(t)!=='done':eff(t)===statusFilter)));const dates=[...new Set(ts.map(t=>t.date))];return section(p?'Project execution tasks':'Daily execution · one consolidated schedule',`<p class="sub">Plan begins Oct 25. Account actions and headset tests belong to Jay; implementation can be assisted. Do the earliest unfinished prerequisites first. Close each work block with evidence; blocked time does not roll forward invisibly.</p><div class="filters">${p?'':`<label>Project<select id="project-filter"><option value="all">All four projects</option>${D.projects.map(x=>`<option value="${x.id}" ${filter===x.id?'selected':''}>${E(x.name)}</option>`).join('')}</select></label>`}<label>Window<select id="range-filter"><option value="build" ${range==='build'?'selected':''}>Build & submission · Oct 25–Nov 18</option><option value="after" ${range==='after'?'selected':''}>Judging & results</option><option value="all" ${range==='all'?'selected':''}>All dates</option></select></label><label>Status<select id="status-filter">${['all','open','doing','blocked','done','deferred'].map(x=>`<option value="${x}" ${statusFilter===x?'selected':''}>${x==='all'?'All statuses':x}</option>`).join('')}</select></label><button id="export-csv">Export full schedule CSV</button></div>${dates.map(d=>{const dt=ts.filter(t=>t.date===d),all=D.tasks.filter(t=>t.date===d),h=hours(sum(all)),c=M.capacityFor(d,state.capacity);return `<div class="daycard ${d===today()?'today':''}"><div class="dhead"><h3>${dateLabel(d)} ${d===today()?'<span class="tag">TODAY</span>':''}</h3><span class="${c!=null&&h>c?'bad':''}">${h}h across all projects · ${c==null?'capacity unset':c+'h available'+(h>c?' · '+Number((h-c).toFixed(2))+'h over':'')}</span></div>${dt.map(taskRow).join('')}</div>`}).join('')||'<p class="empty">No tasks match these filters.</p>'}`);}
function comparison(){return section('Original dashboard → verified position',`<p>The original Muse checklist records <b>7 / 63 historical checks</b> (11%). Its latest visible history entry is Oct 5. Neither that count nor the 4 / 4 prototype-delivery count measures remaining contest scope.</p><p><a href="https://muse.ai/library/artifacts/progress-dashboard" target="_blank" rel="noopener">Original Muse Living Table dashboard ↗</a></p><div class="tablewrap"><table><thead><tr><th>Issue</th><th>Original source</th><th>Corrected interpretation</th></tr></thead><tbody>${D.corrections.map(x=>`<tr><td><b>${E(x[0])}</b><p class="sub">${E(x[3])}</p></td><td>${E(x[1])}</td><td>${E(x[2])}</td></tr>`).join('')}</tbody></table></div>`)+section('Living Table · every original phase reconciled',D.phases.map(p=>`<article class="phase"><h3>${p.id} · ${E(p.title)} <span class="tag">${E(p.status)}</span></h3><p class="sub">Original window: ${E(p.originalDates)}</p><div class="two"><div><b>Original exit</b><p>${E(p.original)}</p></div><div><b>Current evidence</b><p>${E(p.current)}</p></div></div><p><b>Required next:</b> ${E(p.next)}</p></article>`).join(''));}
function evidence(){return section('Source register · checked Oct 25, 2026',`<p>Evidence classes stay separate: <b>verified artifact</b>, <b>official published information</b>, <b>historical source report</b>, and <b>proposed plan</b>. Future work is never seeded as done.</p><div class="source"><b>Verified local build</b><p>Builds/LivingTable-Quest.apk · 66,037,926 bytes · signed ARM64 APK. Build succeeded with 0 errors and 978 warnings. Installation succeeded in the prior session; gameplay acceptance is unverified.</p><code>SHA256 b6995a6422b9e26a745dcde9bd6991a34d70f19ea64e21eb3bacdcea0aa3368d</code><p class="sub">Build report size 1.29 GB is not the APK file size. Unity 6000.3.9f1 / Meta XR 207. No MRUK package found in current manifest/lock.</p></div><div class="source"><b>Verified source backup gap</b><p>Assets/LivingTable and Assets/MRBoardMVP are untracked in Project 26. A Git remote exists, but that does not prove these new files are backed up.</p></div><div class="source"><b>Reviewed original Muse plan</b><p><a href="https://muse.ai/library/artifacts/progress-dashboard" target="_blank" rel="noopener">Living Table progress dashboard</a> · 7/63 historical checks; latest visible log Oct 5. Calendar phase is not an exit-gate result.</p></div><div class="source"><b>User-supplied reference</b><p>index (1).html · Oct 24 Contest Command Dashboard. Source of the four-contest strategy and visual design. Downloaded HTML does not include the originating browser’s saved checkbox state. Application receipts, private prototypes, filing status and written rulings remain unverified.</p></div><div class="source"><b>Related ideas are not additional staffed projects</b><p>The upload reports Studio Pipeline Agent as the chosen hackathon fallback, with Living Table, CradleAI Director and RoomCopilot as alternatives. Those remote prototypes were not verified locally. They receive no additional build allocation; changing entry requires a new scope and eligibility review.</p></div><div class="source"><b>Detailed installed-build tracker</b><p><a href="https://living-table-progress-jz.mistamischif.chatgpt.site" target="_blank" rel="noopener">Open Living Table headset checklist ↗</a> · Separate browser-local records; not automatically synchronized with this hub. Its prior “Muse unavailable” statement is superseded by this review.</p></div>`)+section('Official contest checks',D.projects.map(p=>`<div class="source"><h3><a href="${p.url}" target="_blank" rel="noopener">${E(p.name)} · official source ↗</a></h3><p>${E(p.rules)}</p></div>`).join(''))+section('Unresolved cross-project gates',`<div class="risk"><b>Eligibility and sponsor support · Jay · before crossover</b>Start’s rules include restrictions on sponsor-funded or preferentially supported technology. The uploaded plan requests a written ruling on hackathon participation. No ruling was found; this dashboard does not decide eligibility. Separate repositories alone do not settle it.</div><div class="risk"><b>Disclosure / filing review · Jay · before public materials</b>The upload reports an Oct 23 filing target and unresolved disclosure checks. No filing or counsel clearance has been verified. Locate the actual record and resolve the stated review gate before publishing sensitive project details.</div><div class="risk"><b>Full rules · Jay · before each entry</b>Meta’s waiver page did not expose readable terms; Unity’s full-rules link is still pending; MegaJam’s Box rules link could not be retrieved. Official summary checks do not substitute for these unread documents.</div><div class="risk"><b>Capacity · Jay · before committing the recovery plan</b>178.5 estimated hours through Nov 18 includes both the relay projects and Living Table recovery. No hours are assumed available. Do not reuse the same time allocation for two projects.</div>`);}
function silo(id){const p=project(id),ts=D.tasks.filter(t=>t.project===id);if(id==='lt')return section('Living Table · Current chess contest plan',`<p>${E(p.baseline)}</p><p>${E(p.risk)}</p><a class="button" href="https://living-table-progress-jz.mistamischif.chatgpt.site">Run the 29 detailed checks →</a><p>Priority 1: prove physical/human/AI/virtual continuity. Priority 2: first-five-minute usability and measured Quest performance. Priority 3: judging package and submission receipt.</p><p>Historical task records are preserved in Daily execution; they are not current acceptance evidence.</p>`);return section(p.name,`<div class="siloheader" style="--c:${p.color}"><span class="tag">${E(p.status)} · baseline Oct 25</span><h3>${E(p.entry)}</h3><p>${E(p.baseline)}</p><p><b>Next:</b> ${E(p.next)}</p></div><div class="callout"><b>Risk to resolve</b>${E(p.risk)}</div><p>${E(p.rules)} <a href="${p.url}" target="_blank" rel="noopener">Official source ↗</a></p><p>${done(ts)} / ${ts.length} planned tasks recorded done · <b>not a readiness percentage</b>.</p><a href="#overview">← Portfolio</a>`)+schedule(id);}
function records(){return section('Your execution records',`<p>Saved in this browser only. Export regularly to move between devices. Import replaces local records after validation; original evidence and estimates remain unchanged.</p><div class="actions"><button id="export-json">Export records JSON</button><label class="button">Choose backup<input type="file" id="import-json" accept="application/json,.json"></label><button id="apply-import" ${pendingImport?'':'disabled'}>Replace with validated backup</button></div><p id="message" role="status">${pendingImport?'Validated backup with '+Object.keys(pendingImport.records).length+' records. Ready to replace local records.':E(storageWarning)}</p><p><b>${Object.keys(state.records).length}</b> manual records · ${done(D.tasks)} currently count as done.</p><div class="tablewrap"><table><thead><tr><th>Task</th><th>Effective status</th><th>Evidence / blocker</th><th>Recorded at</th></tr></thead><tbody>${D.tasks.filter(t=>state.records[t.id]).map(t=>`<tr><td>${E(t.title)}</td><td>${E(eff(t))}</td><td class="note">${E(state.records[t.id].note)}</td><td>${E(state.records[t.id].updated)}</td></tr>`).join('')}</tbody></table></div>`);}
function render(){let route=location.hash.slice(1)||'overview';if(!['overview','schedule','comparison','evidence','records',...D.projects.map(p=>p.id)].includes(route))route='overview';$('#app').innerHTML=(storageWarning?`<p class="callout">${E(storageWarning)}</p>`:'')+(route==='overview'?portfolio():route==='schedule'?section('Capacity & collisions',capacityPanel())+schedule():route==='comparison'?comparison():route==='evidence'?evidence():route==='records'?records():silo(route));document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));bind();}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function bind(){document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{editing=D.tasks.find(t=>t.id===b.dataset.task);const r=state.records[editing.id];$('#edit-title').textContent=editing.title;$('#edit-output').textContent=editing.output;$('#edit-deps').textContent=editing.depends.length?'Prerequisites: '+editing.depends.map(id=>{const t=D.tasks.find(t=>t.id===id);return t.title+' ['+eff(t)+']';}).join('; '):'No task prerequisites.';$('#edit-status').value=r?.status||'todo';$('#edit-note').value=r?.note||'';$('#edit-error').textContent='';$('#editor').showModal();});
 if($('#save-capacity'))$('#save-capacity').onclick=()=>{const c={};for(const i of document.querySelectorAll('[data-capacity]')){if(!i.checkValidity()){i.reportValidity();return;}c[i.dataset.capacity]=i.value===''?null:Number(i.value);}state.capacity=c;persist();render();};
 if($('#project-filter'))$('#project-filter').onchange=e=>{filter=e.target.value;render();};if($('#range-filter'))$('#range-filter').onchange=e=>{range=e.target.value;render();};if($('#status-filter'))$('#status-filter').onchange=e=>{statusFilter=e.target.value;render();};
 if($('#export-json'))$('#export-json').onclick=()=>download('contest-command-records.json',JSON.stringify(state,null,2),'application/json');
 if($('#import-json'))$('#import-json').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('Backup exceeds 2 MB.');pendingImport=M.validate(JSON.parse(await f.text()),D.tasks);render();}catch(err){pendingImport=null;$('#message').textContent=err.message;$('#apply-import').disabled=true;}};
 if($('#apply-import'))$('#apply-import').onclick=()=>{if(pendingImport){state=pendingImport;pendingImport=null;persist();render();}};
 if($('#export-csv'))$('#export-csv').onclick=()=>{const q=x=>'"'+String(x).replace(/"/g,'""')+'"';download('contest-command-schedule.csv',[['Date','Project','Task','Estimated minutes','Owner','Prerequisites','Required evidence','Status'],...D.tasks.map(t=>[t.date,project(t.project).name,t.title,t.minutes,t.owner,t.depends.join('; '),t.output,eff(t)])].map(r=>r.map(q).join(',')).join('\r\n'),'text/csv');};}
$('#cancel').onclick=()=>$('#editor').close();$('#taskform').onsubmit=e=>{e.preventDefault();const status=$('#edit-status').value,note=$('#edit-note').value.trim();if(['done','blocked','deferred'].includes(status)&&!note){$('#edit-error').textContent='Add evidence or a concrete reason before saving this status.';return;}if(status==='done'&&editing.depends.some(id=>M.effective(id,state.records,D.tasks)!=='done')){$('#edit-error').textContent='Complete the prerequisite records first. Record this task as blocked or in progress meanwhile.';return;}state.records[editing.id]={status,note,updated:new Date().toISOString()};persist();$('#editor').close();render();};
addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});clock();setInterval(clock,60000);render();
})().catch(err=>{document.querySelector('#app').textContent='The dashboard could not load. Reload the page. '+err.message;});
